// src/lib/ai-ticker.ts
// AI analysis engine for ticker items.
// Called by the cron job (src/app/api/cron/ticker/route.ts) to generate
// 300+ word legal analysis summaries for ticker items.
//
// TODO: Integrate with OpenRouter/OpenAI when API key is available.
// For now, returns a placeholder summary.

export async function generateAISummary(
  headline: string,
  sourceContent: string,
  locale: "en" | "ar",
): Promise<string> {
  const disclaimerEn =
    "\n\n---\n*This summary was generated by AI. It is for informational purposes only and does not constitute legal advice. Tasheel Legal is not responsible for any reliance on this information.*";
  const disclaimerAr =
    "\n\n---\n*تم إنشاء هذا الملخص بواسطة الذكاء الاصطناعي. وهو لأغراض المعلومات فقط ولا يشكل مشورة قانونية. شركة تسهيل للمحاماة غير مسؤولة عن أي اعتماد على هذه المعلومات.*";

  if (locale === "ar") {
    return (
      `تحليل قانوني: ${headline}\n\n` +
      `يأتي هذا التطور في إطار التغيرات التنظيمية المتسارعة في المملكة العربية السعودية، والتي تهدف إلى تعزيز بيئة الأعمال وجذب الاستثمارات. ` +
      `من الناحية القانونية، يتعين على الشركات العاملة في هذا القطاع مراجعة التزاماتها التعاقدية والتنظيمية لضمان الامتثال للأنظمة الجديدة. ` +
      `يوصي فريق تسهيل للمحاماة بإجراء تقييم شامل للمخاطر القانونية، وتحديث العقود والاتفاقيات، والتعاون مع المستشارين القانونiens لضمان التوافق مع المتطلبات النظامية. ` +
      `كما ننصح بمتابعة التحديثات التنظيمية بشكل دوري، والاستعداد للتغييرات المستقبلية التي قد تؤثر على العمليات التجارية.\n\n` +
      disclaimerAr
    );
  }

  return (
    `Legal Analysis: ${headline}\n\n` +
    `This development comes amid rapid regulatory changes in the Kingdom of Saudi Arabia, aimed at enhancing the business environment and attracting investment. ` +
    `From a legal perspective, companies operating in this sector must review their contractual and regulatory obligations to ensure compliance with new regulations. ` +
    `Tasheel Legal recommends conducting a comprehensive legal risk assessment, updating contracts and agreements, and engaging with legal counsel to ensure alignment with regulatory requirements. ` +
    `We also advise regularly monitoring regulatory updates and preparing for future changes that may impact business operations.\n\n` +
    disclaimerEn
  );
}
